export interface GlossaryEntry {
  key: string;
  term: string;
  /** one-line definition (tooltip) */
  short: string;
  /** fuller explanation, paragraphs separated by blank lines; supports [[links]] */
  body: string;
  /** a Kōwhai Café example */
  example?: string;
  /** a common beginner mistake */
  mistake?: string;
  /** deep-dive page */
  href?: string;
  category: "basics" | "recording" | "statements" | "adjustments" | "gst" | "payroll" | "tax" | "business" | "us";
  /** for US terms: the key of the NZ equivalent */
  nz?: string;
}

const g = (e: GlossaryEntry) => e;

export const GLOSSARY: GlossaryEntry[] = [
  // ───────── BASICS ─────────
  g({ key: "accounting", term: "Accounting", category: "basics", short: "Recording, organising and reporting a business's financial activity so people can make decisions.",
    body: "Accounting is the system a business uses to keep track of its money: what it owns, what it owes, what it earned and what it spent.\n\nIt has two halves. **Bookkeeping** is recording every transaction. **Reporting** is summarising those records into [[financial-statements]] that owners, banks and IRD can understand.",
    example: "Every coffee Kōwhai Café sells, every bag of beans it buys and every wage it pays is recorded. At year end, those records become a profit & loss statement and a balance sheet.", href: "/foundations/what-is-accounting" }),
  g({ key: "transaction", term: "Transaction", category: "basics", short: "Any event that changes the business's financial position and can be measured in money.",
    body: "A transaction is something that actually happened between the business and someone else (or inside the business) that changes what it owns, owes, earns or spends.\n\nA test: can you put a dollar figure on it, and does it change at least two accounts? If yes, it gets recorded.",
    example: "Buying an espresso machine is a transaction. Aroha deciding which machine she *likes* is not, until she buys it.", mistake: "Recording a quote, a phone call or an order that hasn't been fulfilled. Nothing has changed yet." }),
  g({ key: "entity-concept", term: "Entity concept", category: "basics", short: "The business is treated as completely separate from its owners.",
    body: "The business keeps its own books, as if it were a separate person, even when one person owns it. For a company this is also the law: a company IS a separate legal person.\n\nSo the owners' private spending never goes into the business accounts. When owners put money in or take money out, it's recorded as a transaction between them and the business.",
    example: "When Aroha buys groceries for her family, that's not in the café's books. When she takes $3,500 from the café account, it's recorded as [[drawings]] against her current account." }),
  g({ key: "asset", term: "Asset", category: "basics", short: "Something the business owns or controls that will bring it future benefit.",
    body: "Assets are resources: cash, money owed to the business, stock, equipment, prepaid costs.\n\n**Current assets** will be used or turned into cash within 12 months (bank, debtors, stock, prepayments). **Non-current assets** last longer (equipment, fit-out, a lease bond).\n\nAssets have a **debit** normal balance: they go UP with a debit.",
    example: "Kōwhai's bank account, its espresso machine, the $6,000 lease bond and the coffee on the shelf are all assets.", href: "/foundations/five-elements" }),
  g({ key: "liability", term: "Liability", category: "basics", short: "Something the business owes to someone else.",
    body: "Liabilities are obligations to pay money (or provide something) in the future: loans, unpaid supplier bills, GST and PAYE owed to IRD, wages owed to staff, customer deposits.\n\n**Current liabilities** are due within 12 months. **Non-current liabilities** are due later.\n\nLiabilities have a **credit** normal balance: they go UP with a credit.",
    example: "The Harbour Bank loan, the GST owed to IRD and unpaid invoices from Southern Roasters are liabilities.", href: "/foundations/five-elements" }),
  g({ key: "equity", term: "Equity", category: "basics", short: "The owners' stake in the business: assets minus liabilities.",
    body: "Equity is what would be left for the owners if the business sold all its assets and paid all its debts. It grows when owners invest money and when the business makes a profit. It shrinks with losses and dividends.\n\nIn a company, equity is mainly **share capital** (what owners paid for their shares) plus **[[retained-earnings]]** (profits kept in the business).\n\nEquity has a **credit** normal balance.",
    example: "Aroha and Ben's $100,000 share capital, plus this year's profit, is Kōwhai's equity.", href: "/foundations/five-elements" }),
  g({ key: "income", term: "Income (revenue)", category: "basics", short: "Money earned from the business's activities. It increases equity.",
    body: "Income is the value of goods and services the business has provided, whether or not it has been paid yet. **Revenue** usually means income from the main business activity (sales). **Other income** covers things like interest.\n\nIncome is recorded excluding GST, and it has a **credit** normal balance.\n\nIncome is not the same as cash received. Borrowing money or owners investing is cash in, but not income.",
    example: "Café sales and catering are revenue. Interest on the term deposit is other income.", mistake: "Treating a bank loan or a customer deposit as income.", href: "/foundations/five-elements" }),
  g({ key: "revenue", term: "Revenue", category: "basics", short: "Income from the main trading activity, usually sales.",
    body: "See [[income]]. On the profit & loss statement, revenue sits at the top, and cost of sales is taken away from it to get gross profit.", example: "Coffee, food and catering sales (excl GST)." }),
  g({ key: "expense", term: "Expense", category: "basics", short: "A cost used up in earning income. It reduces equity.",
    body: "Expenses are resources used up during the period: stock sold, wages, rent, power, depreciation, interest.\n\nThey have a **debit** normal balance. An expense is recorded when it is **incurred** (used), not when it is paid. That's the [[accrual-basis]].",
    example: "April's rent, wages, the power bill and merchant fees are expenses.", mistake: "Recording the purchase of an asset (like the espresso machine) as an expense, or treating loan principal repayments as expenses.", href: "/foundations/five-elements" }),
  g({ key: "accounting-equation", term: "Accounting equation", category: "basics", short: "Assets = Liabilities + Equity. It always balances.",
    body: "Everything a business owns (assets) was paid for either with borrowed money (liabilities) or with the owners' money and profits (equity). So **Assets = Liabilities + Equity**, always.\n\nDuring the year, profit hasn't been moved into equity yet, so the expanded version is:\n**Assets = Liabilities + Share capital + Retained earnings + (Income − Expenses)**.\n\nEvery transaction keeps the equation balanced. That's what [[double-entry]] guarantees.",
    example: "After the shareholders invest and the loan is drawn: Assets $150,000 = Liabilities $50,000 + Equity $100,000.", href: "/foundations/accounting-equation" }),
  g({ key: "double-entry", term: "Double-entry bookkeeping", category: "basics", short: "Every transaction affects at least two accounts, with equal debits and credits.",
    body: "Every transaction has two sides: something is received and something is given. Double entry records both, as a [[debit]] in one account and an equal [[credit]] in another (or several).\n\nBecause debits always equal credits, the books stay in balance, and many errors can be caught with a [[trial-balance]].",
    example: "Buying beans on credit: Purchases goes up (debit $2,000), GST claimable (debit $300), and Accounts payable goes up (credit $2,300). Total debits $2,300 = total credits $2,300.", href: "/foundations/double-entry" }),
  g({ key: "debit", term: "Debit (Dr)", category: "basics", short: "The LEFT side of an account. Increases assets & expenses; decreases liabilities, equity & income.",
    body: "'Debit' just means **left side**. It does NOT mean bad, or money going out.\n\nA debit **increases**: Assets, Expenses (and Drawings).\nA debit **decreases**: Liabilities, Equity, Income.\n\nA common memory aid is **DEAD CLIC**: **D**ebits increase **E**xpenses, **A**ssets, **D**rawings; **C**redits increase **L**iabilities, **I**ncome, **C**apital.",
    example: "Money into the bank is a debit to Bank (asset up).", mistake: "Thinking 'debit' means money leaving. On your personal bank statement the bank uses its own point of view, which is the opposite.", href: "/foundations/debits-credits" }),
  g({ key: "credit", term: "Credit (Cr)", category: "basics", short: "The RIGHT side of an account. Increases liabilities, equity & income; decreases assets & expenses.",
    body: "'Credit' just means **right side**.\n\nA credit **increases**: Liabilities, Equity (capital), Income.\nA credit **decreases**: Assets, Expenses.\n\nEvery transaction's credits must equal its debits.",
    example: "Recording a sale credits Sales (income up). Paying from the bank credits Bank (asset down).", href: "/foundations/debits-credits" }),
  g({ key: "normal-balance", term: "Normal balance", category: "basics", short: "The side (debit or credit) that makes an account go up.",
    body: "Assets and expenses normally have debit balances. Liabilities, equity and income normally have credit balances. An account sitting on its 'wrong' side is a warning sign, or a special case like an overdrawn bank account or a GST refund due." }),
  g({ key: "chart-of-accounts", term: "Chart of accounts", category: "recording", short: "The numbered list of every account the business uses.",
    body: "The chart of accounts is the filing system of the books. Each account has a code, a name and a type. Codes are grouped so the type is obvious: Kōwhai uses 1xx assets, 2xx liabilities, 3xx equity, 4xx income, 5xx cost of sales, 6xx expenses.\n\nIt's set up once and grows as needed. Accounting software like Xero or MYOB comes with a default NZ chart you adapt.",
    example: "610 Rent, 200 Accounts payable, 100 Bank.", href: "/foundations/chart-of-accounts" }),
  g({ key: "account", term: "Account", category: "recording", short: "A record that collects every increase and decrease for one item.",
    body: "Each asset, liability, equity, income and expense item has its own account. It shows the opening balance, every debit and credit, and the closing balance. Picture it as a [[t-account]]." }),

  // ───────── RECORDING ─────────
  g({ key: "source-document", term: "Source document", category: "recording", short: "The original evidence of a transaction: an invoice, receipt, payslip, bank statement…",
    body: "Every entry in the books must be backed by evidence. Source documents prove the transaction happened and give the details (date, amount, GST, who).\n\nNZ law requires businesses to keep them for **7 years**. GST claims also need [[taxable-supply-information]].",
    example: "Southern Roasters' tax invoice, the POS Z-report, Mia's payslip, the stocktake sheet.", href: "/foundations/source-documents" }),
  g({ key: "journal", term: "Journal", category: "recording", short: "The book of original entry: transactions recorded in date order as debits and credits.",
    body: "Before amounts go into individual accounts, they're written in a journal, in date order, showing which accounts are debited and credited and why (the narration).\n\nBusinesses often use **special journals** for frequent transactions (sales, purchases, cash receipts, cash payments, payroll) and the [[general-journal]] for everything else.",
    href: "/cycle/journalise" }),
  g({ key: "general-journal", term: "General journal", category: "recording", short: "The journal for entries that don't fit a special journal: adjustments, corrections, closing entries.",
    body: "Month-end and year-end adjustments, depreciation, accruals, error corrections and closing entries all go through the general journal, each with a 'journal voucher' explaining it.",
    example: "Moving one month of prepaid rent to rent expense." }),
  g({ key: "special-journals", term: "Special journals", category: "recording", short: "Separate journals for high-volume transaction types (sales, purchases, receipts, payments, payroll).",
    body: "Instead of writing hundreds of similar entries in one general journal, they're grouped: a **sales journal**, a **purchases journal**, a **cash receipts journal**, a **cash payments journal**, and a **payroll journal**. Totals are posted to the ledger periodically.\n\nIn modern software these are the 'Sales', 'Bills', 'Bank' and 'Payroll' screens." }),
  g({ key: "compound-entry", term: "Compound entry", category: "recording", short: "A journal entry with more than one debit or more than one credit.",
    body: "Many transactions affect three or more accounts. A sale paid partly by card and partly by cash, with GST, has two debits and two credits. The rule is the same: total debits = total credits." }),
  g({ key: "ledger", term: "Ledger (general ledger)", category: "recording", short: "The collection of all accounts, each showing its full history and balance.",
    body: "After journalising, each line is **posted** to its account in the ledger. The ledger lets you see, for example, every movement in the bank account and its running balance.\n\nThe **general ledger** holds every account. **Subsidiary ledgers** hold the detail behind a [[control-account]], such as one account per customer or supplier.",
    href: "/cycle/post" }),
  g({ key: "posting", term: "Posting", category: "recording", short: "Copying journal lines into the ledger accounts.",
    body: "Each debit in the journal becomes a debit in that account in the ledger, and each credit becomes a credit. Software does this instantly, but understanding it is the key to reading any account." }),
  g({ key: "t-account", term: "T-account", category: "recording", short: "A simple picture of an account: debits on the left, credits on the right.",
    body: "Draw a big T. Put the account name on top, debits on the left, credits on the right. Add up both sides; the difference is the balance, on whichever side is bigger.\n\nAccountants still sketch T-accounts to think through tricky entries.",
    href: "/foundations/t-accounts" }),
  g({ key: "control-account", term: "Control account", category: "recording", short: "A general-ledger account whose total is backed by a detailed subsidiary ledger.",
    body: "Accounts receivable shows ONE total of what all customers owe. The detail (who owes what) is in the debtors subsidiary ledger. The total of the subsidiary ledger must equal the control account.",
    example: "Accounts payable $13,547 = Southern Roasters + Fresh Fields + Valley Dairy + GreenCup balances." }),
  g({ key: "subsidiary-ledger", term: "Subsidiary ledger", category: "recording", short: "Detailed records per customer (debtors ledger) or per supplier (creditors ledger).",
    body: "See [[control-account]]. It's used to send customer statements, chase overdue invoices and check supplier statements." }),
  g({ key: "trial-balance", term: "Trial balance", category: "recording", short: "A list of every account balance, checking that total debits = total credits.",
    body: "After posting, every account's balance is listed in a debit or credit column. If the columns don't match, there's an error somewhere.\n\nBut a balancing trial balance doesn't prove the books are right. Errors like posting to the wrong account, or forgetting a transaction entirely, still balance.",
    href: "/cycle/unadjusted-tb" }),
  g({ key: "accounts-receivable", term: "Accounts receivable (debtors)", category: "recording", short: "Money customers owe the business for sales on credit.",
    body: "When the café invoices a customer and gives them time to pay, it records the income AND an asset, accounts receivable. When the customer pays, the receivable turns into cash. That payment is not income again.",
    example: "Tūī Consulting owes $1,150 from 18 April until it pays on 8 May." }),
  g({ key: "accounts-payable", term: "Accounts payable (creditors)", category: "recording", short: "Money the business owes suppliers for purchases on credit.",
    body: "When a supplier invoice arrives, the expense (or asset) is recorded along with a liability, accounts payable. Paying the bill clears the liability. It is not an expense again.",
    example: "Southern Roasters' invoice due on the 20th of the following month." }),
  g({ key: "z-report", term: "Z-report", category: "recording", short: "The end-of-day (or period) sales total from a POS or till, which resets the counters.",
    body: "Cafés don't journal every coffee. The POS keeps the detail, and the Z-report summarises sales by payment type and category, including the GST content. It's the source document for the daily or weekly sales entry." }),
  g({ key: "float", term: "Float", category: "recording", short: "A fixed amount of cash kept in the till to give change.",
    body: "The float is not income. It's the business's own money moved from the bank to the till. At banking time, everything above the float is deposited." }),
  g({ key: "eftpos-clearing", term: "EFTPOS clearing account", category: "recording", short: "A holding account for card sales the bank hasn't paid out yet.",
    body: "When a customer taps their card, the sale has happened, but the money arrives in the bank 1–2 days later (net of fees). The clearing account holds it in between. It should always be close to zero, apart from the most recent day or two of sales.",
    example: "Card sales on 31 March settle on 1 April, so they're in EFTPOS clearing on the year-end balance sheet." }),
  g({ key: "merchant-fees", term: "Merchant fees", category: "recording", short: "What the bank charges the business for accepting card payments.",
    body: "In NZ, traditional EFTPOS (debit card, inserted with a PIN) usually has no per-transaction fee, but contactless and credit card payments cost the merchant around 0.5–2%. These fees are financial services, which are **GST-exempt**." }),
  g({ key: "principal", term: "Principal", category: "recording", short: "The amount actually borrowed (as opposed to interest).",
    body: "Loan repayments have two parts: **interest** (an expense, the cost of borrowing) and **principal** (repaying the debt, which reduces the liability). On a table loan the payment stays the same, but each month more of it is principal and less is interest." }),
  g({ key: "interest", term: "Interest", category: "recording", short: "The cost of borrowing money (expense), or the reward for lending it (income).",
    body: "Interest paid on a business loan is a deductible expense. Interest earned is income, and the bank deducts [[rwt]] from it. Both are GST-exempt financial services." }),

  // ───────── ACCRUAL & ADJUSTMENTS ─────────
  g({ key: "accrual-basis", term: "Accrual basis", category: "adjustments", short: "Record income when earned and expenses when incurred, regardless of when cash moves.",
    body: "Under accrual accounting, the question is 'when did it happen?', not 'when was it paid?'. A sale on credit is income on the day of the sale. A power bill for March is a March expense even if paid in April.\n\nThis gives a true picture of each period's profit, which is why NZ companies prepare their financial statements on an accrual basis.\n\nThe alternative, the **cash basis**, records only when money moves. It's simpler, but it can distort results badly.",
    href: "/foundations/cash-vs-accrual" }),
  g({ key: "cash-basis", term: "Cash basis", category: "adjustments", short: "Record income and expenses only when cash is received or paid.",
    body: "Simple, but misleading: paying a year's insurance up front makes one month look terrible. Small sole traders sometimes use it for their own tracking. For tax and company reporting, accruals are generally required.", href: "/foundations/cash-vs-accrual" }),
  g({ key: "adjusting-entry", term: "Adjusting entry", category: "adjustments", short: "A period-end journal entry that makes the accounts follow the accrual basis.",
    body: "Day-to-day bookkeeping mostly follows documents and cash. At period end, adjustments fix the timing so that income and expenses land in the right period: accruals, prepayments, depreciation, stock, bad debts, holiday pay and tax.\n\nAdjustments usually don't involve the bank.",
    href: "/cycle/adjustments" }),
  g({ key: "prepayment", term: "Prepayment (prepaid expense)", category: "adjustments", short: "A cost paid in advance for a future period. It's an asset until used.",
    body: "If you pay now for something you'll use later, you haven't used it up yet. You own a right to future service, which is an asset. Each month, the used part moves to expense.",
    example: "Three months' rent paid on 3 April; the unused 6 months of an insurance policy at 31 March." }),
  g({ key: "accrued-expense", term: "Accrued expense", category: "adjustments", short: "A cost already used up but not yet billed or paid. It's a liability.",
    body: "At year end, some costs have been incurred but no invoice has arrived. They're estimated and recorded as an expense plus a liability.\n\nIn NZ, no GST is claimed on an accrual, because you can only claim GST once you hold the tax invoice.",
    example: "March's power, estimated at $520 because the bill arrives on 8 April." }),
  g({ key: "accrued-income", term: "Accrued income", category: "adjustments", short: "Income earned but not yet invoiced. It's an asset.",
    body: "Work done before balance date belongs in this year's income, even if the invoice goes out next month.", example: "Catering done on 30 March, invoiced in April." }),
  g({ key: "income-in-advance", term: "Income in advance (unearned income)", category: "adjustments", short: "Money received for goods or services not yet provided. It's a liability.",
    body: "A deposit isn't income until the work is done, because the business still owes the service or a refund.\n\nGST twist: GST is triggered by the EARLIER of an invoice or a payment, so the deposit's GST is returned straight away.",
    example: "The $1,150 wedding deposit received in March for an April wedding." }),
  g({ key: "depreciation", term: "Depreciation", category: "adjustments", short: "Spreading the cost of a long-lived asset over the years it's used.",
    body: "Fixed assets wear out or become obsolete. Rather than expensing them all at once, their cost is spread over their useful life.\n\nIRD sets rates for every asset type. Two methods:\n• **Diminishing value (DV)**: a fixed % of the remaining book value each year. Bigger deductions early.\n• **Straight line (SL)**: a fixed % of the original cost each year. The same amount every year.\n\nThe credit goes to **accumulated depreciation** (a [[contra-account]]), so the cost stays visible.",
    href: "/nz/depreciation" }),
  g({ key: "contra-account", term: "Contra account", category: "adjustments", short: "An account that offsets another, e.g. accumulated depreciation reduces an asset.",
    body: "A contra-asset has a credit balance even though it sits with assets. Cost minus accumulated depreciation = **book value** (carrying amount)." }),
  g({ key: "book-value", term: "Book value (carrying amount)", category: "adjustments", short: "Cost minus accumulated depreciation.",
    body: "The value at which an asset is shown in the accounts. It's not the market value. The **tax book value** (adjusted tax value) can differ, for example because of Investment Boost." }),
  g({ key: "capital-expenditure", term: "Capital expenditure", category: "adjustments", short: "Spending on assets that last more than a year. Capitalised, then depreciated.",
    body: "Capital spending creates or improves a long-term asset. **Revenue expenditure** (repairs, running costs) is expensed straight away. The line matters for both the accounts and tax.\n\nTest: does it give a benefit beyond this year, or improve the asset beyond its original condition? Then it's capital.",
    example: "Buying the espresso machine = capital. Replacing the grinder burrs = repair (revenue)." }),
  g({ key: "low-value-asset", term: "Low-value asset", category: "adjustments", short: "An asset costing $1,000 or less (excl GST) that can be expensed immediately.",
    body: "NZ tax law lets businesses deduct assets costing $1,000 or less straight away instead of depreciating them. Identical items bought together are tested on the combined cost. Low-value assets can't also get Investment Boost.", href: "/nz/depreciation" }),
  g({ key: "investment-boost", term: "Investment Boost", category: "tax", short: "An extra 20% up-front tax deduction for NEW business assets bought from 22 May 2025.",
    body: "Introduced in Budget 2025. A business can deduct 20% of the cost of a new (or newly imported) asset in the year it's first used, and then claim normal depreciation on the remaining 80%.\n\nIt's a tax-only rule. The accounts still depreciate the full cost, which creates a difference between accounting profit and taxable income. Residential buildings, second-hand NZ assets and low-value assets don't qualify.",
    href: "/nz/depreciation" }),
  g({ key: "inventory", term: "Inventory (stock)", category: "adjustments", short: "Goods held for sale or for making products to sell.",
    body: "For a café: beans, milk, food ingredients, packaging. Valued at cost (or net realisable value if lower). See [[periodic-inventory]].", href: "/nz/inventory" }),
  g({ key: "periodic-inventory", term: "Periodic inventory system", category: "adjustments", short: "Purchases are expensed as bought; a stocktake at period end works out what's left.",
    body: "Most small cafés use this method. All stock purchases go to Purchases accounts during the year. At year end a physical count (stocktake) values the stock on hand, and an adjustment moves that amount back onto the balance sheet.\n\nThe alternative, a **perpetual** system, updates stock with every sale. Retailers with barcodes use it.",
    href: "/nz/inventory" }),
  g({ key: "cost-of-goods-sold", term: "Cost of goods sold (COGS)", category: "statements", short: "Opening stock + purchases − closing stock.",
    body: "The cost of the stock actually sold during the period. Revenue − COGS = **gross profit**.\n\nCafés watch their COGS % closely. Around 28–35% of sales is typical.", example: "Kōwhai: $0 opening + $135,377 purchases − $3,800 closing = $131,577." }),
  g({ key: "stocktake", term: "Stocktake", category: "adjustments", short: "Physically counting and valuing stock on hand.",
    body: "Done at balance date (or close to it, with adjustments). IRD requires trading stock to be valued at year end, although businesses with turnover under $1.3m and stock estimated under $10,000 can choose to use opening stock as closing stock." }),
  g({ key: "bad-debt", term: "Bad debt", category: "adjustments", short: "A customer debt that won't be collected and is written off.",
    body: "When there's no realistic chance of getting paid, the debt is removed from receivables and expensed.\n\nTax: it's deductible only when actually written off before balance date. A **doubtful debts** provision (an estimate of debts that might go bad) is an accounting estimate that isn't deductible.\n\nGST (invoice basis): the GST paid on the original invoice can be claimed back.",
    example: "Pop-Up Events went into liquidation owing $920." }),
  g({ key: "holiday-pay", term: "Holiday pay", category: "payroll", short: "Pay for annual leave. Accrued as a liability, or paid as 8% each pay for casuals.",
    body: "Permanent employees build up 4 weeks' annual leave a year (available after 12 months). Until it's taken, the employer owes it, so it's accrued as a liability.\n\nCasual or fixed-term (under 12 months) employees can be paid 8% of gross earnings with each pay instead ('pay-as-you-go'), and only if their employment agreement says so.",
    href: "/nz/holidays" }),
  g({ key: "materiality", term: "Materiality", category: "statements", short: "Only items big enough to affect a reader's decisions need precise treatment.",
    body: "Accountants don't chase every cent. A $5 prepaid item at year end isn't worth an adjustment. What's 'material' depends on the size of the business." }),
  g({ key: "going-concern", term: "Going concern", category: "statements", short: "Assume the business will keep trading for the foreseeable future.",
    body: "This is why assets are shown at cost less depreciation, not at fire-sale prices. If a business is likely to close, the accounts must be prepared differently." }),

  // ───────── STATEMENTS & CYCLE ─────────
  g({ key: "accounting-cycle", term: "Accounting cycle", category: "statements", short: "The repeating steps from transaction to financial statements and back to a new period.",
    body: "Identify → analyse → journalise → post → trial balance → reconcile → adjust → adjusted trial balance → financial statements → close → post-closing trial balance → start again.", href: "/cycle" }),
  g({ key: "financial-statements", term: "Financial statements", category: "statements", short: "The formal reports: performance (P&L), position (balance sheet), changes in equity, cash flows, and notes.",
    body: "In NZ they're often called the **Statement of Financial Performance** and the **Statement of Financial Position**. Small companies must prepare at least minimum special-purpose financial statements for tax.", href: "/cycle/statements" }),
  g({ key: "profit-and-loss", term: "Profit & loss (Statement of Financial Performance)", category: "statements", short: "Income minus expenses for a period: did the business make money?",
    body: "Shows revenue, cost of sales, gross profit, other income, expenses, profit before tax, tax, and profit after tax for a period (e.g. 1 April – 31 March)." }),
  g({ key: "balance-sheet", term: "Balance sheet (Statement of Financial Position)", category: "statements", short: "A snapshot of assets, liabilities and equity at one date.",
    body: "Shows what the business owns and owes at balance date. Total assets − total liabilities = net assets = total equity." }),
  g({ key: "cash-flow-statement", term: "Cash flow statement", category: "statements", short: "Where cash came from and went, in three groups: operating, investing, financing.",
    body: "Profit isn't cash. The cash flow statement explains the change in the bank balance.\n\n**Direct method**: lists actual receipts and payments.\n**Indirect method**: starts from profit and adjusts for non-cash items and changes in working capital." }),
  g({ key: "gross-profit", term: "Gross profit", category: "statements", short: "Revenue minus cost of goods sold.", body: "What's left from sales after paying for the stock, available to cover wages, rent and overheads." }),
  g({ key: "net-profit", term: "Net profit", category: "statements", short: "What's left after ALL expenses (before or after tax).", body: "The bottom line. Net profit after tax increases retained earnings." }),
  g({ key: "working-capital", term: "Working capital", category: "statements", short: "Current assets minus current liabilities.", body: "A measure of short-term financial health. It shows whether the business can pay bills due in the next 12 months." }),
  g({ key: "retained-earnings", term: "Retained earnings", category: "statements", short: "Accumulated profits kept in the business (not paid out as dividends).",
    body: "Each year's profit after tax is added (via closing entries), and dividends are subtracted. It's part of equity." }),
  g({ key: "closing-entries", term: "Closing entries", category: "statements", short: "Year-end entries that zero all income and expense accounts and move the profit to retained earnings.",
    body: "Income and expense accounts measure ONE period, so they're temporary. At year end they're emptied into an [[income-summary]], and the profit moves to retained earnings. Balance-sheet accounts are permanent and carry forward.", href: "/cycle/closing" }),
  g({ key: "income-summary", term: "Income summary", category: "statements", short: "A temporary account used only while closing the books.", body: "Collects all income (credits) and expenses (debits). Its balance equals net profit, which is then moved to retained earnings." }),
  g({ key: "balance-date", term: "Balance date", category: "statements", short: "The last day of the financial year. In NZ it's usually 31 March.",
    body: "The standard NZ balance date is 31 March, matching the tax year. Businesses can apply to IRD for a different one (e.g. 30 June)." }),
  g({ key: "bank-reconciliation", term: "Bank reconciliation", category: "statements", short: "Matching the books' bank account to the bank statement and explaining every difference.",
    body: "Differences come from **timing** (deposits in transit, unpresented payments) and from **items the bank knows about first** (fees, interest, direct debits, dishonoured payments). Those get entered in the books.\n\nDone monthly (or daily in modern software via bank feeds).", href: "/cycle/bank-reconciliation" }),
  g({ key: "deposit-in-transit", term: "Deposit in transit", category: "statements", short: "Money recorded as banked in the books that the bank hasn't processed yet.", body: "A timing difference. It needs no entry, but it's listed in the reconciliation." }),
  g({ key: "unpresented-payment", term: "Unpresented payment", category: "statements", short: "A payment recorded in the books that hasn't cleared the bank yet.", body: "Traditionally a cheque not yet banked by the payee. NZ banks stopped cheques in 2021, so today it's usually a late-night online payment or a batch processed the next day." }),
  g({ key: "reversing-entry", term: "Reversing entry", category: "statements", short: "An optional entry on the first day of the new year that undoes an accrual.",
    body: "This avoids double-counting. When March's power bill arrives in April, it can be entered normally, because the reversing entry has already cancelled the accrual.",
    example: "On 1 April 2027 Kōwhai reverses last year's accrued wages. The 7 April pay run is then entered in full, and the reversal cancels the 9 days that belonged to last year.", href: "/on-the-job?year=2&step=REVERSALS" }),
  g({ key: "comparatives", term: "Comparatives", category: "statements", short: "Last year's figures shown next to this year's in the financial statements.",
    body: "From the second year on, every statement shows two columns: this year and last year. Readers can see what changed, and why it matters, at a glance.",
    example: "Kōwhai's 2028 profit & loss shows café sales for both years side by side.", href: "/on-the-job/year-2-statements" }),

  // ───────── GST ─────────
  g({ key: "gst", term: "GST (Goods and Services Tax)", category: "gst", short: "A 15% tax on most goods and services in NZ, collected by businesses for IRD.",
    body: "Registered businesses add 15% GST to their sales (**output tax**) and claim back the GST on their business purchases (**input tax**). They pay IRD the difference, or get a refund if inputs are bigger.\n\nFor a registered business, GST is NOT income or expense. It's money held for IRD, which is why income and expenses are recorded excl GST.\n\nRegistration is compulsory once turnover exceeds (or is expected to exceed) **$60,000** in 12 months.",
    example: "A $5.75 flat white includes $0.75 GST. Kōwhai keeps $5.00.", href: "/nz/gst" }),
  g({ key: "output-tax", term: "Output tax", category: "gst", short: "GST charged on sales.", body: "Collected from customers and owed to IRD. Credit to the GST account." }),
  g({ key: "input-tax", term: "Input tax", category: "gst", short: "GST paid on business purchases, claimable from IRD.", body: "Debit to the GST account. Needs taxable supply information as evidence." }),
  g({ key: "taxable-supply-information", term: "Taxable supply information (tax invoice)", category: "gst", short: "The details a GST invoice/receipt must contain (rules since April 2023).",
    body: "Since 1 April 2023 the term 'tax invoice' has been replaced by 'taxable supply information' (TSI), though most people still say tax invoice. What's required depends on value:\n\n• **$200 or less**: supplier name, date, description, total paid.\n• **Over $200**: also the supplier's GST number and the GST amount (or 'incl GST').\n• **Over $1,000**: also the buyer's name and an identifier (address, phone, email, NZBN, etc.).",
    href: "/nz/gst" }),
  g({ key: "zero-rated", term: "Zero-rated supply", category: "gst", short: "A taxable supply charged at 0% GST. You can still claim GST on related costs.",
    body: "Examples: exported goods, the sale of a going concern between registered persons, most land sales between registered businesses." }),
  g({ key: "exempt-supply", term: "Exempt supply", category: "gst", short: "A supply that has no GST at all: financial services, residential rent, donated goods sold by charities.",
    body: "No GST is charged, and GST on costs related to making exempt supplies can't be claimed. Bank fees, interest and merchant fees are exempt, so there's no GST to claim." }),
  g({ key: "invoice-basis", term: "Invoice basis (GST)", category: "gst", short: "GST is accounted for when an invoice is issued or received, or payment made if earlier.",
    body: "Matches accrual accounting. Kōwhai uses it. The alternative is the **payments basis** (GST only when cash moves, available if turnover is under $2m), and there's also a **hybrid** basis.", href: "/nz/gst" }),
  g({ key: "payments-basis", term: "Payments basis (GST)", category: "gst", short: "GST is accounted for only when money is received or paid.", body: "Simpler for small businesses with lots of credit sales. Turnover must be $2 million or less." }),
  g({ key: "gst-return", term: "GST return (GST101A)", category: "gst", short: "The form that calculates GST to pay or refund for a period.", body: "Filed monthly, two-monthly or six-monthly, generally due on the 28th of the month after the period ends (with special dates for January and May).", href: "/nz/gst-return" }),

  // ───────── PAYROLL ─────────
  g({ key: "gross-pay", term: "Gross pay", category: "payroll", short: "Total pay before any deductions.", body: "Hours × rate (+ allowances, overtime, holiday pay). The employer's wages expense is the gross figure." }),
  g({ key: "net-pay", term: "Net pay (take-home)", category: "payroll", short: "Gross pay minus PAYE, student loan, KiwiSaver and other deductions.", body: "What actually lands in the employee's bank account." }),
  g({ key: "paye", term: "PAYE (Pay As You Earn)", category: "payroll", short: "Income tax the employer deducts from wages and pays to IRD.",
    body: "Employers calculate tax on each pay using the employee's **tax code**, deduct it, and pay it to IRD. In NZ, the PAYE figure includes the **ACC earners' levy**.\n\nSmall employers (PAYE under $500,000 a year) pay by the **20th of the following month**.", href: "/nz/paye" }),
  g({ key: "tax-code", term: "Tax code", category: "payroll", short: "Tells the employer how much PAYE to deduct (M, ME, S, SH, SB…).",
    body: "Employees fill in an IR330 form. M = main job. ME = main job with the independent earner tax credit. S/SH/ST/SA/SB = secondary jobs at flat rates. Adding 'SL' means a student loan. With no IR330, the employer must deduct at the non-declaration rate (45%).", href: "/nz/paye" }),
  g({ key: "ietc", term: "Independent earner tax credit (IETC)", category: "payroll", short: "Up to $520 a year off tax for people earning $24,000–$70,000 without other support.", body: "Claimed through the ME tax code. It reduces by 13c per dollar over $66,000." }),
  g({ key: "acc-earners-levy", term: "ACC earners' levy", category: "payroll", short: "A levy on wages funding non-work injury cover. Included in PAYE.", body: "$1.75 per $100 of earnings (incl GST) for 2026–27, up to maximum liable earnings of $156,641.", href: "/nz/acc" }),
  g({ key: "student-loan", term: "Student loan deductions", category: "payroll", short: "12c per dollar earned over the repayment threshold ($24,128 a year / $928 a fortnight).", body: "Deducted by the employer when the tax code includes SL, and paid to IRD with PAYE." }),
  g({ key: "kiwisaver", term: "KiwiSaver", category: "payroll", short: "NZ's voluntary retirement savings scheme with compulsory employer contributions for members.",
    body: "Employees contribute 3.5% (the default from 1 April 2026), 4, 6, 8 or 10% of gross pay. Employers must contribute at least 3.5% on top. All of it goes to IRD with PAYE, and IRD passes it to the KiwiSaver provider.", href: "/nz/kiwisaver" }),
  g({ key: "esct", term: "ESCT (Employer Superannuation Contribution Tax)", category: "payroll", short: "Tax deducted from the employer's KiwiSaver contribution.",
    body: "Employer contributions are a taxable benefit, so the employer deducts ESCT from them at a rate based on the employee's earnings (10.5%–39%). The employee's fund receives the net amount.", href: "/nz/kiwisaver" }),
  g({ key: "payday-filing", term: "Payday filing", category: "payroll", short: "Sending IRD each pay run's details within 2 working days of payday.",
    body: "Since 2019, employers must file 'employment information' every payday (gross pay, PAYE, deductions, and new or departing employees). Payroll software does it automatically.", href: "/nz/paye" }),

  // ───────── TAX ─────────
  g({ key: "ird", term: "IRD (Inland Revenue / Te Tari Taake)", category: "tax", short: "NZ's tax department: collects income tax, GST, PAYE, and runs KiwiSaver and student loans.", body: "Most dealings are through myIR online." }),
  g({ key: "provisional-tax", term: "Provisional tax", category: "tax", short: "Paying income tax during the year in instalments instead of all at the end.",
    body: "If last year's residual income tax (RIT) was over $5,000, you must pay provisional tax this year, usually in 3 instalments (28 Aug, 15 Jan, 7 May for a March balance date). Methods: **standard** (last year + 5%), **estimation**, or **AIM** (accounting-software based).", href: "/nz/provisional-tax" }),
  g({ key: "terminal-tax", term: "Terminal tax", category: "tax", short: "The balance of income tax due after provisional tax and credits.",
    body: "Due 7 February after the end of the tax year, or 7 April if you have a tax agent with an extension of time.", href: "/nz/provisional-tax" }),
  g({ key: "rwt", term: "RWT (Resident Withholding Tax)", category: "tax", short: "Tax deducted by banks from interest (and from some dividends) before paying it.",
    body: "It's a prepayment of the recipient's income tax, credited against the final bill. Companies default to 28%." }),
  g({ key: "imputation-credit", term: "Imputation credit", category: "tax", short: "A credit for tax the company has already paid, attached to dividends.",
    body: "Stops company profits being taxed twice. When a company pays a dividend with imputation credits, shareholders get credit for the company tax already paid.", href: "/nz/shareholders" }),
  g({ key: "imputation-credit-account", term: "Imputation credit account (ICA)", category: "tax", short: "A company's running record of the income tax it has paid, which it can pass on to shareholders as imputation credits.",
    body: "It's a memorandum account kept for IRD, not part of the ledger. Tax payments (provisional, terminal, RWT deducted) are credits. Imputation credits attached to dividends are debits. It must not be in debit at 31 March.",
    example: "Before paying its first dividend, Kōwhai's ICA held the year-1 voluntary payment, the RWT on the term deposit and two provisional instalments.", href: "/nz/shareholders" }),
  g({ key: "solvency-test", term: "Solvency test", category: "tax", short: "The test directors must pass before a company pays a dividend: it can pay its debts, and assets exceed liabilities.",
    body: "Under the Companies Act 1993 (s 4), a company is solvent if it can pay its debts as they fall due in the normal course of business, and the value of its assets is greater than its liabilities (including contingent liabilities). Directors who vote for a dividend must sign a certificate that the company will pass the test immediately after it (s 52).",
    mistake: "Thinking a dividend needs retained earnings. NZ law is about solvency, not about the balance of retained earnings.", href: "/nz/shareholders" }),
  g({ key: "depreciation-recovery", term: "Depreciation recovery", category: "tax", short: "Taxable income when an asset sells for more than its tax book value.",
    body: "The excess is the depreciation that turned out not to be a real loss in value, so IRD claws it back. It's capped at the total depreciation claimed (including Investment Boost). Anything above the original cost is a capital gain, which usually isn't taxed.",
    example: "Kōwhai's old POS system had a tax book value of $800 and sold for $900: $100 of depreciation recovery income.", href: "/nz/depreciation" }),
  g({ key: "dividend", term: "Dividend", category: "tax", short: "A distribution of company profits to shareholders.", body: "It's a reduction in retained earnings, not an expense. Usually fully imputed at 28%, with 5% supplementary RWT deducted on top.", href: "/nz/shareholders" }),
  g({ key: "drawings", term: "Drawings", category: "tax", short: "Money or goods an owner takes out of the business for personal use.",
    body: "Drawings aren't an expense. For a sole trader they reduce equity. For a company they're debited to the shareholder's [[shareholder-current-account]].", href: "/nz/shareholders" }),
  g({ key: "shareholder-current-account", term: "Shareholder current account", category: "tax", short: "A running account of money between a shareholder and their company.",
    body: "Credits (salary allocated, money lent to the company) mean the company owes the shareholder. Debits (drawings) reduce it.\n\nIf it goes **overdrawn** (the shareholder owes the company), the company must charge interest at IRD's prescribed rate, or face FBT / deemed dividend consequences.", href: "/nz/shareholders" }),
  g({ key: "shareholder-salary", term: "Shareholder salary", category: "tax", short: "Salary paid to a working shareholder without PAYE, often set at year end.",
    body: "Companies can pay shareholder-employees a salary that isn't subject to PAYE, as long as they aren't also on regular PAYE wages. It's deductible to the company and taxed in the shareholder's own IR3 (often with personal provisional tax). The ACC CoverPlus Extra or work levy is invoiced later.", href: "/nz/shareholders" }),
  g({ key: "entertainment", term: "Entertainment expenses (50% rule)", category: "tax", short: "Business food, drink and recreation with a private element is only 50% deductible.",
    body: "Includes client lunches, staff parties, corporate boxes and holiday accommodation. Light refreshments at work (morning tea) are 100% deductible.\n\nThe GST on the non-deductible 50% must also be paid back, through an adjustment in the GST return at year end.", href: "/nz/income-tax" }),
  g({ key: "ir4", term: "IR4", category: "tax", short: "The company income tax return.", body: "Filed annually. It includes the financial statements summary (IR10) and the tax reconciliation." }),
  g({ key: "ir3", term: "IR3", category: "tax", short: "The individual income tax return for people with income not taxed at source.", body: "Shareholder salaries, rental income, self-employed income." }),
  g({ key: "uomi", term: "Use-of-money interest (UOMI)", category: "tax", short: "Interest IRD charges on tax paid late (or pays on tax overpaid).", body: "From 16 January 2026: 8.97% on underpayments, 2.25% on overpayments." }),
  g({ key: "fbt", term: "FBT (Fringe Benefit Tax)", category: "tax", short: "Tax paid by employers on non-cash benefits given to employees (e.g. a work car used privately).", href: "/nz/other-taxes", body: "Paid quarterly or annually. A café rarely has FBT, unless (for example) a shareholder-employee drives a company van home." }),
  g({ key: "acc-levy", term: "ACC work levy", category: "tax", short: "An annual levy the employer pays ACC to fund workplace injury cover.", href: "/nz/acc", body: "Invoiced by ACC once a year based on total payroll and the industry's risk classification (cafés have their own levy rate)." }),

  // ───────── BUSINESS ─────────
  g({ key: "sole-trader", term: "Sole trader", category: "business", short: "One person in business on their own, with no legal separation from the business.", body: "Simplest structure. Profit is taxed at personal rates, and the owner is personally liable for all debts.", href: "/foundations/business-structures" }),
  g({ key: "partnership", term: "Partnership", category: "business", short: "Two or more people in business together, sharing profits and liability.", body: "Files an IR7. Each partner pays tax on their share.", href: "/foundations/business-structures" }),
  g({ key: "company", term: "Company", category: "business", short: "A separate legal entity owned by shareholders, with limited liability.", body: "Taxed at 28%. Registered with the Companies Office, which requires an annual return. Directors have legal duties under the Companies Act 1993.", href: "/foundations/business-structures" }),
  g({ key: "look-through-company", term: "Look-through company (LTC)", category: "business", short: "A company whose profits and losses are taxed in the owners' hands.", body: "Has limited liability, but is taxed like a partnership. Popular for property investment.", href: "/foundations/business-structures" }),
  g({ key: "share-capital", term: "Share capital", category: "business", short: "Money shareholders pay the company for their shares.", body: "Part of equity. It's not income and not a loan." }),

  // ───────── US TERMS → NZ ─────────
  g({ key: "us-withdrawals", term: "Withdrawals (US)", category: "us", nz: "drawings", short: "US term. In NZ: **drawings**.", body: "The owner taking cash or goods out of the business for personal use. The entry is the same: debit withdrawals/drawings, credit cash/bank. It reduces equity and isn't an expense.\n\nIn an NZ company like Kōwhai, a shareholder's drawings go to their [[shareholder-current-account]].", href: "/us-vs-nz" }),
  g({ key: "us-revenue-element", term: "Revenue (as an element) (US)", category: "us", nz: "income", short: "US term. In NZ the element is **income**, which includes revenue and gains.", body: "US GAAP lists revenues and gains as separate elements. NZ IFRS has one element, [[income]], made up of [[revenue]] (normal trading, like café sales) plus gains (one-offs, like selling equipment above book value).", href: "/us-vs-nz" }),
  g({ key: "us-income-statement", term: "Income statement (US)", category: "us", nz: "profit-and-loss", short: "US term. In NZ: **statement of financial performance**, or **profit & loss (P&L)**.", body: "Same statement: income minus expenses for a period. NZ IFRS formally calls it the statement of profit or loss (and other comprehensive income). Small NZ businesses just say P&L.", href: "/us-vs-nz" }),
  g({ key: "us-balance-sheet", term: "Balance sheet (US & NZ)", category: "us", nz: "balance-sheet", short: "Used in both countries. NZ's formal name is the **statement of financial position**.", body: "Same statement: assets, liabilities and equity at one date. You'll see both names in NZ.", href: "/us-vs-nz" }),
  g({ key: "us-retained-earnings-statement", term: "Statement of retained earnings / stockholders' equity (US)", category: "us", nz: "retained-earnings", short: "US term. In NZ: **statement of changes in equity**.", body: "Shows how equity moved during the year: profit added, dividends paid, shares issued.", href: "/us-vs-nz" }),
  g({ key: "us-stockholders", term: "Stockholders / common stock (US)", category: "us", nz: "share-capital", short: "US terms. In NZ: **shareholders** and **share capital** (ordinary shares).", body: "NZ shares have no par value, so there's no “additional paid-in capital” account. Everything paid for shares goes to [[share-capital]].", href: "/us-vs-nz" }),
  g({ key: "us-sales-tax", term: "Sales tax (US)", category: "us", nz: "gst", short: "US tax. NZ has **GST** instead, and it works differently.", body: "US sales tax is charged by states and cities, mostly only to the final customer, and businesses can't claim back tax they pay on their own purchases.\n\nNZ [[gst]] is 15% everywhere, charged at every stage, and registered businesses claim back the GST they pay ([[input-tax]]). So for an NZ business, GST is a pass-through account, never a cost.", href: "/us-vs-nz" }),
  g({ key: "us-fica", term: "FICA / payroll taxes (US)", category: "us", nz: "paye", short: "US payroll taxes. In NZ: **PAYE** (incl ACC earners' levy) plus **KiwiSaver**.", body: "US employees and employers each pay FICA (Social Security + Medicare) on wages, plus income-tax withholding and unemployment taxes.\n\nNZ has no employer social-security tax. Employees have [[paye]] deducted (which includes the [[acc-earners-levy]]), and employers must contribute 3.5% to [[kiwisaver]] for members (less [[esct]]).", href: "/us-vs-nz" }),
  g({ key: "us-w4", term: "W-4 / W-2 (US)", category: "us", nz: "tax-code", short: "US payroll forms. In NZ: the **IR330** tax code declaration and payday filing.", body: "A W-4 tells a US employer how much to withhold; NZ's equivalent is the IR330, which sets the employee's [[tax-code]]. Instead of a year-end W-2, NZ employers report every pay to IRD through [[payday-filing]].", href: "/us-vs-nz" }),
  g({ key: "us-irs", term: "IRS (US)", category: "us", nz: "ird", short: "US tax agency. In NZ: **IRD** (Inland Revenue, Te Tari Taake).", body: "IRD collects income tax, GST, PAYE and KiwiSaver, and runs student loans.", href: "/us-vs-nz" }),
  g({ key: "us-fiscal-year", term: "Fiscal year (US)", category: "us", nz: "balance-date", short: "US term (often 1 Jan – 31 Dec). NZ's income year runs **1 April – 31 March**.", body: "The last day of the year is the [[balance-date]]. Businesses can apply to IRD for a different balance date, but 31 March is the norm.", href: "/us-vs-nz" }),
  g({ key: "us-llc", term: "LLC / S corporation (US)", category: "us", nz: "look-through-company", short: "US business structures. NZ's nearest equivalents are a **company** or a **look-through company (LTC)**.", body: "An S corp passes profit to its owners for tax, much like an NZ [[look-through-company]]. An LLC can be taxed several ways in the US; in NZ you'd choose between a [[company]] (taxed at 28%) and an LTC.", href: "/us-vs-nz" }),
  g({ key: "us-sole-proprietorship", term: "Sole proprietorship (US)", category: "us", nz: "sole-trader", short: "US term. In NZ: **sole trader**.", body: "One person in business with no legal separation from the business. Same idea, different name.", href: "/us-vs-nz" }),
  g({ key: "us-merchandise-inventory", term: "Merchandise inventory (US)", category: "us", nz: "inventory", short: "US term. In NZ: **inventory** or **stock** (“trading stock” in tax law).", body: "Note that US GAAP allows the LIFO valuation method. NZ doesn't: use FIFO or weighted average.", href: "/us-vs-nz" }),
  g({ key: "us-notes-payable", term: "Notes payable (US)", category: "us", nz: "liability", short: "US term. In NZ usually just a **loan** or **term loan**.", body: "A written promise to repay borrowed money. Kōwhai's equivalent is its $50,000 bank loan.", href: "/us-vs-nz" }),
  g({ key: "us-checking-account", term: "Checking account / checks (US)", category: "us", nz: "bank-reconciliation", short: "US term. In NZ: **cheque account** or transaction account.", body: "NZ banks stopped issuing cheques around 2021. Payments are EFTPOS, direct debit and online transfers, which is why “outstanding checks” become unpresented payments in an NZ bank reconciliation.", href: "/us-vs-nz" }),
];

export const GLOSSARY_MAP: Record<string, GlossaryEntry> = Object.fromEntries(GLOSSARY.map((e) => [e.key, e]));
